package com.example.examplemod.cargo.center;

import com.example.examplemod.cargo.CargoTrainRegistry;
import com.example.examplemod.economy.EconomyManager;
import com.simibubi.create.content.trains.RailwaySavedData;
import com.simibubi.create.content.trains.graph.EdgePointType;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerPlayer;
import java.util.*;

/** Server-authoritative road preview, public-fleet registration and debt repayment workspace. */
public final class RailCenter {
    private RailCenter(){}
    private record Preview(UUID token,long expiry,OwnerRef owner,String name,long rate,RailRoutes.Path path,CompoundTag values){}
    private static final Map<ServerPlayer,Preview> PREVIEWS=new WeakHashMap<>();
    public static CompoundTag previewRoad(ServerPlayer actor,CompoundTag values){
        var owner=CenterOperations.owner(values.getString("Owner"));if(!owner.manages(actor.getServer(),actor.getUUID()))throw new IllegalArgumentException("rail_permission");long rate=CenterOperations.number(values,"Rate");if(rate<0||rate>1_000_000_000L)throw new IllegalArgumentException("rail_tariff_invalid");
        UUID from=CenterOperations.id(values,"FirstStation"),to=CenterOperations.id(values,"LastStation");if(from.equals(to))throw new IllegalArgumentException("rail_route_missing");
        RailRoutes.Path path;
        if(values.contains("ViaStation")&&!values.getString("ViaStation").isBlank()){
            UUID via=CenterOperations.id(values,"ViaStation");var first=RailRoutes.between(actor.getServer(),from,via,null,owner,"FASTEST",0).orElseThrow(()->new IllegalArgumentException("rail_route_missing"));var last=RailRoutes.between(actor.getServer(),via,to,null,owner,"FASTEST",0).orElseThrow(()->new IllegalArgumentException("rail_route_missing"));var segments=new ArrayList<>(first.segments());segments.addAll(last.segments());path=new RailRoutes.Path(to,first.backwards(),segments,first.distance()+last.distance());
        }else path=RailRoutes.between(actor.getServer(),from,to,null,owner,"FASTEST",0).orElseThrow(()->new IllegalArgumentException("rail_route_missing"));
        var preview=new Preview(UUID.randomUUID(),actor.serverLevel().getGameTime()+1200,owner,CargoInfrastructure.name(values.getString("Name")),rate,path,values.copy());PREVIEWS.put(actor,preview);
        var t=new CompoundTag();t.putUUID("Token",preview.token());t.putUUID("PathFingerprint",path.fingerprint());t.putDouble("Distance",path.distance());t.putLong("Total",0);t.putLong("Rate",rate);t.putString("Source",CargoRailConnections.station(actor.getServer(),from).station().name);t.putString("Destination",CargoRailConnections.station(actor.getServer(),to).station().name);var map=new CompoundTag();map.put("Rails",RailRoutes.geometry(actor.getServer(),path,"ROAD"));map.put("Markers",new ListTag());map.putBoolean("RouteFound",true);t.put("MapPreview",map);t.put("MapValues",values.copy());return t;
    }
    public static void execute(ServerPlayer actor,CompoundTag q){var s=actor.getServer();var values=q.getCompound("Values");var book=EconomyManager.get(actor.serverLevel()).roadTolls();book.captureLegacy(EconomyManager.get(actor.serverLevel()).cargo().orders());String action=q.getString("Action");
        switch(action){
            case "ROAD_REGISTER"->{var p=PREVIEWS.get(actor);if(!q.getBoolean("Confirmed")||p==null||!q.hasUUID("QuoteToken")||!p.token().equals(q.getUUID("QuoteToken"))||p.expiry()<actor.serverLevel().getGameTime()||!p.values().equals(values)||!p.owner().manages(s,actor.getUUID())||!RailRoutes.valid(s,p.path()))throw new IllegalArgumentException("delivery_quote_changed");book.register(q.getUUID("Request"),p.owner(),p.name(),p.rate(),p.path().spans());PREVIEWS.remove(actor);}
            case "ROAD_RATE","ROAD_CLOSE"->{var road=book.road(q.getUUID("Selected")).orElseThrow();if(!road.owner().manages(s,actor.getUUID()))throw new IllegalArgumentException("rail_permission");book.revise(road.id(),action.equals("ROAD_RATE")?CenterOperations.number(values,"Rate"):road.rate(),!action.equals("ROAD_CLOSE"));}
            case "FLEET_PUBLISH"->PublicFleetRegistry.get(s).publish(actor,CenterOperations.id(values,"Train"),CenterOperations.owner(values.getString("Owner")),CenterOperations.id(values,"HomeStation"),CenterOperations.number(values,"Rate"),CenterOperations.number(values,"DispatchFee"));
            case "FLEET_DISABLE"->PublicFleetRegistry.get(s).disable(actor,q.getUUID("Selected"));
            case "DEBT_PAY"->{var debt=book.debts().stream().filter(d->d.id().equals(q.getUUID("Selected"))).findFirst().orElseThrow();if(!debt.debtor().canSpend(s,actor.getUUID()))throw new IllegalArgumentException("rail_permission");if(book.repay(debt.id(),CenterOperations.number(values,"Amount"),q.getUUID("Request"))<=0)throw new IllegalArgumentException("rail_payment_unavailable");}
            default->throw new IllegalArgumentException("rail_action_unknown");
        }
    }
    public static CompoundTag snapshot(ServerPlayer actor,CompoundTag q){var s=actor.getServer();var data=new CompoundTag();var rows=new ListTag();var choices=new CompoundTag();var forms=new ListTag();String section=q.getString("Section");var book=EconomyManager.get(actor.serverLevel()).roadTolls();
        var stations=new ListTag();for(var graph:RailwaySavedData.load(s).getTrackNetworks().values())for(var station:graph.getPoints(EdgePointType.STATION))if(!station.assembling)option(stations,station.id,station.name);choices.put("RailStations",stations);
        var trains=new ListTag();for(var train:RailwaySavedData.load(s).getTrains().values()){var registered=CargoTrainRegistry.find(s,train.id).orElse(null);boolean manage=registered==null?actor.getUUID().equals(train.owner):CargoOwners.get(s).owner("train/"+train.id,registered.ownerId()).manages(s,actor.getUUID());if(manage)option(trains,train.id,train.name.getString());}choices.put("FleetTrains",trains);
        if(section.equals("roads")){CenterForms.add(forms,"ROAD_REGISTER",false,"Name","Owner@Owners","FirstStation@RailStations","LastStation@RailStations","ViaStation@OptionalRailStations","Rate#0");var optional=new ListTag();var none=new CompoundTag();none.putString("Value","");none.putString("Name","—");optional.add(none);stations.forEach(x->optional.add(x.copy()));choices.put("OptionalRailStations",optional);
            for(var road:book.roads()){var row=CenterService.row(road.id(),road.name(),road.owner().name(s),road.active()?"ACTIVE":"CLOSED");row.putString("Kind","road");row.putBoolean("Manage",road.owner().manages(s,actor.getUUID()));row.putLong("Rate",road.rate());row.putString("OwnerName",road.owner().name(s));double length=road.spans().stream().mapToDouble(x->x.to()-x.from()).sum();row.putDouble("Distance",length);var details=new ListTag();detail(details,"Тариф CR / 1000 блоков",Long.toString(road.rate()));detail(details,"Длина",Long.toString(Math.round(length)));row.put("Details",details);rows.add(row);if(q.hasUUID("Selected")&&q.getUUID("Selected").equals(road.id())&&row.getBoolean("Manage")){CenterForms.add(forms,"ROAD_RATE",true,"Rate#0");if(road.active())CenterForms.add(forms,"ROAD_CLOSE",true);}}}
        if(section.equals("fleet")){CenterForms.add(forms,"FLEET_PUBLISH",false,"Train@FleetTrains","Owner@Owners","HomeStation@RailStations","Rate#0","DispatchFee#0");for(var service:PublicFleetRegistry.get(s).services()){var row=CenterService.row(service.train(),service.name(),service.owner().name(s),PublicFleetRegistry.get(s).state(s,service));row.putString("Kind","fleet");var registration=CargoTrainRegistry.find(s,service.train()).orElse(null);row.putBoolean("Manage",(registration==null?service.owner():CargoOwners.get(s).owner("train/"+service.train(),registration.ownerId())).manages(s,actor.getUUID()));row.putLong("Rate",service.rate());row.putLong("DispatchFee",service.dispatchFee());row.putUUID("Home",service.home());rows.add(row);if(q.hasUUID("Selected")&&q.getUUID("Selected").equals(service.train())&&row.getBoolean("Manage")&&service.enabled())CenterForms.add(forms,"FLEET_DISABLE",true);}}
        if(section.equals("debts"))for(var debt:book.debts())if(actor.hasPermissions(2)||debt.debtor().operates(s,actor.getUUID())||debt.creditor().operates(s,actor.getUUID())){var row=CenterService.row(debt.id(),debt.debtor().name(s),debt.creditor().name(s),debt.remaining()==0?"PAID":"DEBT");row.putString("Kind","debt");row.putBoolean("Manage",debt.debtor().canSpend(s,actor.getUUID()));row.putLong("Amount",debt.remaining());row.putLong("Assessed",debt.assessed());row.putLong("Paid",debt.paid());rows.add(row);if(q.hasUUID("Selected")&&q.getUUID("Selected").equals(debt.id())&&row.getBoolean("Manage")&&debt.remaining()>0)CenterForms.add(forms,"DEBT_PAY",true,"Amount#1");}
        if(section.equals("debts")&&actor.hasPermissions(2))for(var debt:book.technicalDebts())if(debt.resolved()==null){var row=CenterService.row(debt.id(),debt.name(),debt.creditor().name(s),"UNRESOLVED");row.putString("Kind","debt");row.putBoolean("Manage",false);row.putBoolean("Technical",true);row.putUUID("Train",debt.train());row.putLong("Assessed",debt.assessed());row.putLong("Paid",0);row.putLong("Amount",debt.assessed());fact(row,"technical_train",debt.train().toString());rows.add(row);}
        for(var raw:rows){var row=(CompoundTag)raw;row.remove("Details");String kind=row.getString("Kind");if(kind.equals("road")){fact(row,"rate",row.getLong("Rate")+" CR / 1000");fact(row,"distance",Long.toString(Math.round(row.getDouble("Distance"))));if(row.getBoolean("Manage")||actor.hasPermissions(2)){var stats=book.statistics(row.getUUID("Id"));fact(row,"travelled",Long.toString(Math.round(stats.getDouble("Distance"))));fact(row,"paid",stats.getLong("Paid")+" CR");fact(row,"remaining",stats.getLong("Outstanding")+" CR");}}if(kind.equals("fleet")){fact(row,"rate",row.getLong("Rate")+" CR / 1000");fact(row,"dispatch",row.getLong("DispatchFee")+" CR");var home=CargoRailConnections.station(s,row.getUUID("Home"));fact(row,"home",home==null?"—":home.station().name);if(row.getBoolean("Manage")||actor.hasPermissions(2))PublicFleetRegistry.get(s).shipment(row.getUUID("Id")).ifPresent(id->{row.putString("Dispatch",PublicFleetRegistry.get(s).progress(id));if(!PublicFleetRegistry.get(s).warning(id).isBlank()){var warning=new CompoundTag();warning.putString("LabelKey","ccec.rail.warning");warning.putString("ValueKey","ccec.center.value."+PublicFleetRegistry.get(s).warning(id));row.getList("Facts",10).add(warning);}});}if(kind.equals("debt")){fact(row,"assessed",row.getLong("Assessed")+" CR");fact(row,"paid",row.getLong("Paid")+" CR");fact(row,"remaining",row.getLong("Amount")+" CR");}}
        for(var raw:forms)for(var field:((CompoundTag)raw).getList("Fields",10)){var f=(CompoundTag)field;f.putString("LabelKey","ccec.rail.field."+f.getString("Key"));f.putString("HintKey","ccec.rail.hint."+f.getString("Key"));if(f.getString("Kind").equals("number")){f.putLong("Min",f.getString("Key").equals("Amount")?1:0);f.putLong("Max",1_000_000_000L);}}
        if(q.hasUUID("Selected"))for(var raw:rows){var row=(CompoundTag)raw;if(row.getUUID("Id").equals(q.getUUID("Selected"))){data.put("SelectedRow",row.copy());break;}}
        int total=rows.size(),pages=Math.max(1,(total+31)/32),page=Math.clamp(q.getInt("Page"),0,pages-1);var visible=new ListTag();for(int i=page*32;i<Math.min(total,(page+1)*32);i++)visible.add(rows.get(i));
        var guide=new CompoundTag();guide.putString("TitleKey","ccec.rail.guide."+section);guide.putString("BodyKey","ccec.rail.guide."+section+".body");data.put("Guide",guide);data.put("Rows",visible);data.putInt("Page",page);data.putInt("Pages",pages);data.putInt("Total",total);data.put("Forms",forms);data.put("Choices",choices);data.put("Map",CargoMapView.snapshot(actor,new CompoundTag(),new ListTag()));return data;
    }
    private static void fact(CompoundTag row,String key,String value){if(!row.contains("Facts"))row.put("Facts",new ListTag());var t=new CompoundTag();t.putString("LabelKey","ccec.rail."+key);t.putString("Value",value);t.putString("Icon","rail");row.getList("Facts",10).add(t);}
    private static void detail(ListTag list,String label,String value){var t=new CompoundTag();t.putString("Label",label);t.putString("Value",value);list.add(t);}
    private static void option(ListTag list,UUID id,String name){if(list.size()>=256)return;var t=new CompoundTag();t.putString("Value",id.toString());t.putString("Name",name);list.add(t);}
}
